// Railway Infrastructure as Code for Accord's hosted demo (project victorious-curiosity, environment production).
// Replaces Config as Code (railway.json), which Railway stops reading on 2026-12-01.
// Generated by `railway config migrate --variables=unmanaged`, then corrected against the live services
// (`railway status --json`, 23 Nov 2026). Railway does not read this file on deploy: it takes effect only through
// `railway config apply`. How to apply and roll back: docs/railway.md.
// Variables are unmanaged: this file never reads or writes a service variable.
import { defineRailway, github, postgres, project, service, volume } from "railway/iac";

export default defineRailway(() => {
  const accord = github("Adityaakr/accord", { branch: "main", checkSuites: false, rootDirectory: "/" });

  // The four services built from this repository use the root Dockerfile (railway.json `build`), restart on
  // failure up to 10 times (what the live deployments run with), one replica in asia-southeast1.
  const dockerfile = { buildEnvironment: "V3", builder: "DOCKERFILE", dockerfilePath: "/Dockerfile" } as const;
  const onFailure = { restartPolicyType: "ON_FAILURE", restartPolicyMaxRetries: 10 } as const;

  const Postgres = postgres("Postgres", { region: "asia-southeast1-eqsg3a" });
  Postgres.deploy = { multiRegionConfig: { "asia-southeast1-eqsg3a": { numReplicas: 1 } } };
  Postgres.networking = { privateNetworkEndpoint: "postgres" };
  const postgresVolume = volume("postgres-volume", { alerts: { usage: { "100": {}, "80": {}, "95": {} } }, allowOnlineResize: true, region: "asia-southeast1-eqsg3a", sizeMB: 50000 });

  // The faucet top-up cron is uploaded with `railway up` (no repository source) and builds with Railpack;
  // `railway config migrate` proposed DOCKERFILE here because it read the repository's railway.json, which this
  // service never used.
  const accordFaucetRefill = service("accord-faucet-refill", {
    build: { buildEnvironment: "V3", builder: "RAILPACK" },
    start: "node refill.mjs",
    replicas: { "asia-southeast1-eqsg3a": 1 },
    deploy: { cronSchedule: "0 */2 * * *", restartPolicyType: "NEVER" },
  });
  const accordKeeper = service("accord-keeper", {
    source: accord,
    build: dockerfile,
    deploy: onFailure,
    replicas: { "asia-southeast1-eqsg3a": 1 },
    networking: { privateNetworkEndpoint: "victorious-creativity" },
  });
  const _accordweb = service("@accord/web", {
    source: accord,
    build: { ...dockerfile, buildCommand: "npm run build --workspace=@accord/web", watchPatterns: ["/apps/web/**"] },
    deploy: onFailure,
    replicas: { "asia-southeast1-eqsg3a": 1 },
    domains: [{ domain: "useaccord.tech", port: 5180 }],
    networking: { privateNetworkEndpoint: "accordweb" },
  });
  const accordAgent = service("accord-agent", {
    source: accord,
    build: dockerfile,
    deploy: onFailure,
    replicas: { "asia-southeast1-eqsg3a": 1 },
    networking: { privateNetworkEndpoint: "carefree-patience" },
  });
  const accord2 = service("accord", {
    source: accord,
    build: dockerfile,
    deploy: onFailure,
    healthcheck: "/app/api/status",
    replicas: { "asia-southeast1-eqsg3a": 1 },
  });

  return project("victorious-curiosity", {
    variables: { managed: false },
    resources: [Postgres, accordFaucetRefill, accordKeeper, _accordweb, accordAgent, accord2, postgresVolume],
  });
});
